import { useState, useEffect } from 'react';
import styles from './InvestmentForm.module.css';

const InvestmentForm = ({ onAddInvestment }) => {
  const [formData, setFormData] = useState({
    brand: '',
    processor: '',
    generation: '',
    initialCost: '',
    salePrice: '',
  });
  
  const [investments, setInvestments] = useState([]); // Estado para todas las inversiones

  // Cargar inversiones al montar el componente
  useEffect(() => {
    const savedInvestments = JSON.parse(localStorage.getItem('investments')) || [];
    setInvestments(savedInvestments);
  }, []);

  const brands = ['Lenovo', 'HP', 'Acer', 'Fujitsu', 'Dell', 'MSI', 'Asus', 'Gateway', 'Lenovo ThinkPad'];
  const processors = ['Intel Celeron', 'Intel Core i3', 'Intel Core i5', 'Intel Core i7', 'Intel Core i9', 'AMD Ryzen 3', 'AMD Ryzen 5', 'AMD Ryzen 7', 'AMD Ryzen 9'];
  const generations = Array.from({ length: 11 }, (_, i) => i + 4);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    
    const initialCost = parseFloat(formData.initialCost) || 0;
    const salePrice = parseFloat(formData.salePrice) || 0;
    const profit = salePrice - initialCost;
    const investmentDate = new Date().toISOString();

    // Crear objeto de inversión
    const newInvestment = {
      ...formData,
      id: Date.now(),
      date: investmentDate,
      initialCost,
      salePrice,
      profit,
    };

    // Actualizar estado local
    const updatedInvestments = [newInvestment, ...investments];
    setInvestments(updatedInvestments);

    // Guardar en localStorage
    localStorage.setItem('investments', JSON.stringify(updatedInvestments));

    // Guardar en historial
    const investmentsHistory = JSON.parse(localStorage.getItem('investmentsHistory')) || [];
    localStorage.setItem(
      'investmentsHistory',
      JSON.stringify([newInvestment, ...investmentsHistory])
    );

    // Actualizar finanzas
    const currentFinance = JSON.parse(localStorage.getItem('financialData')) || {
      totalIncome: 0,
      totalExpenses: 0,
      balance: 0,
      currentBalance: 0,
    };

    const updatedFinance = {
      ...currentFinance,
      totalIncome: (currentFinance.totalIncome || 0) + salePrice,
      totalExpenses: (currentFinance.totalExpenses || 0) + initialCost,
      balance: (currentFinance.balance || 0) + profit,
      currentBalance: (currentFinance.currentBalance || 0) + profit,
    };

    localStorage.setItem('financialData', JSON.stringify(updatedFinance));

    // Notificar al componente padre
    onAddInvestment && onAddInvestment(newInvestment);

    // Resetear formulario
    setFormData({
      brand: '',
      processor: '',
      generation: '',
      initialCost: '',
      salePrice: '',
    });
  };

  const handleDelete = (id) => {
    const filteredInvestments = investments.filter(investment => investment.id !== id);
    setInvestments(filteredInvestments);
    localStorage.setItem('investments', JSON.stringify(filteredInvestments));
  };

  return (
    <div className={styles.container}>
      <form className={styles.form} onSubmit={handleSubmit}>
        <h2>Registrar Inversión en Laptop</h2>
        <select name="brand" value={formData.brand} onChange={handleChange} >
          <option value="" disabled>Selecciona una marca</option>
          {brands.map((brand, index) => (
            <option key={index} value={brand}>{brand}</option>
          ))}
        </select>
        <select name="processor" value={formData.processor} onChange={handleChange} >
          <option value="" disabled>Selecciona un procesador</option>
          {processors.map((processor, index) => (
            <option key={index} value={processor}>{processor}</option>
          ))}
        </select>
        <select name="generation" value={formData.generation} onChange={handleChange} required>
          <option value="" disabled>Selecciona una generación</option>
          {generations.map((generation) => (
                        <option key={generation} value={generation}>{generation}ª Generación</option>
                      ))}
                    </select>
                    <input
                      type="number"
                      name="initialCost"
                      placeholder="Costo Inicial"
                      value={formData.initialCost}
                      onChange={handleChange}
                      required
                      min="0"
                      step="0.01"
                    />
                    <input
                      type="number"
                      name="salePrice"
                      placeholder="Precio de Venta"
                      value={formData.salePrice}
                      onChange={handleChange}
                      required
                      min="0"
                      step="0.01"
                    />
                    <button type="submit">Agregar Inversión</button>
                  </form>
            
                  {/* Lista de todas las inversiones */}
                  <div className={styles.investmentsList}>
                    {investments.map((investment) => (
                      <div key={investment.id} className={styles.card}>
                        <h3>Inversión #{investment.id.toString().slice(-4)}</h3>
                        <p><strong>Marca:</strong> {investment.brand}</p>
                        <p><strong>Procesador:</strong> {investment.processor}</p>
                        <p><strong>Generación:</strong> {investment.generation}ª</p>
                        <p><strong>Costo Inicial:</strong> ${investment.initialCost.toFixed(2)}</p>
                        <p><strong>Precio de Venta:</strong> ${investment.salePrice.toFixed(2)}</p>
                        <p className={investment.profit >= 0 ? styles.profit : styles.loss}>
                          <strong>Ganancia:</strong> ${investment.profit.toFixed(2)}
                        </p>
                        <div className={styles.cardFooter}>
                          <small>{new Date(investment.date).toLocaleString()}</small>
                          <button 
                            onClick={() => handleDelete(investment.id)}
                            className={styles.deleteButton}
                          >
                            Eliminar
                          </button>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              );
            };
            
            export default InvestmentForm;
